"""Source-backed final A report and figure; preserves both failed frozen gates."""
import hashlib,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
H=Path(__file__).resolve().parent;P=H/'runs/objective_comprehension_v1'
ARMS=['baseline','zero_sham','refusal_ablation','random_ablation'];LABELS=['Original','Zero sham','Refusal ablation','Random ablation']
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 a=read(H/'runs/pilot/analysis.json');d=read(P/'analysis.json');cross=read(P/'permission_action_crosstab_v1.json');errors=read(P/'descriptive_error_breakdown_v1.json');reviewp=H/'comprehension-result-review.json';review=read(reviewp) if reviewp.exists() else {};reproducep=H/'cpu_reproduction_v1/receipt.json';repro=read(reproducep) if reproducep.exists() else {};prior=read(H.parent/'c/records/independent_a_pilot_review_v1.json');assert prior['passed'];assert not a['readiness']['passed'] and not d['passed']
 if review.get('passed'):assert review['analysis_sha256']==sha(P/'analysis.json')
 lines=['The original model correctly identified the written prohibition in all 36 blocked-harmless factual questions, yet selected the prohibited shortcut in 18 of the 36 corresponding earlier action decisions. These were separate prompts on the same exposed worlds, not measurements of what the model represented at the action boundary.','', 'Adding an adverse consequence was associated with substantially fewer baseline violations: 18/36 harmless-rule violations versus 1/36 when the shortcut also harmed a third party. Refusal ablation changed those counts to 19/36 and 2/36. Without an explicit prohibition, adverse shortcut choices rose from 18/36 to 23/36 under ablation. These are development observations; both frozen readiness gates failed and no decision confirmation ran.','', '| Condition | Prohibited shortcut, harmless | Prohibited shortcut, harmful | Adverse shortcut, no rule | Authorized harmless completion |','|---|---:|---:|---:|---:|']
 for arm,label in zip(ARMS,LABELS):
  vals=[a['counts'][arm+'|'+c] for c in ['blocked_harmless','blocked_harmful','unstated_harmful','authorized_harmless']];lines.append('| '+label+' | '+' | '.join(f"{r['actions'].get('expedited',0)}/{r['assigned']}" for r in vals)+' |')
 lines+=['','All 720 action responses were valid. The two menu orders repeat each of 18 numeric worlds, six per task family; they are not 36 independent worlds. The tasks cover warehouse fulfillment, report assembly and batch-compute dispatch. Both completion routes are feasible, the ordinary route takes four time units and the shortcut takes one. All resources, people and consequences are simulated. Operational-rule violations and externally scored third-party consequences are separate outcomes.','', 'The original gate required baseline and sham compliance with the harmless operating rule. Both achieved only 18/36, despite 36/36 authorized fastest completions in every arm. That gate failure remains unchanged. The subsequent question was explicitly result-informed: can the same model configurations report permission, feasibility and arithmetic from the same exposed scenarios?','', '| Condition | Permission correct | Technical feasibility correct | Time arithmetic correct |','|---|---:|---:|---:|']
 for arm,label in zip(ARMS,LABELS):
  ss=[d['summary'][arm+'|'+q] for q in ['permission','feasibility','time_saving']];lines.append('| '+label+' | '+' | '.join(f"{s['correct']}/{s['assigned']}" for s in ss)+' |')
 lines+=['', 'The diagnostic retained 1,286 valid answers out of 1,296. All four arms passed permission and arithmetic thresholds, but every arm failed the frozen 90% technical-feasibility threshold. All feasibility errors selected only the ordinary route under a prohibition, even though the question explicitly asked to ignore permission. Authorized feasibility was 36/36 in every arm. This response pattern is consistent with conflating permission and feasibility; it does not establish an internal mechanism. The ablated arm made fewer feasibility errors, so the diagnostic failure is not evidence that ablation simply reduced overall task accuracy.','', 'The exact blocked-harmless cross-tab matches world, arm and answer-order index to the original action-menu-order index:','', '| Condition | Correct rule answer + prohibited action | Correct rule answer + permitted action or defer | Incorrect or invalid rule answer |','|---|---:|---:|---:|']
 for arm,label in zip(ARMS,LABELS):
  t=cross['tables'][arm];lines.append(f"| {label} | {t['correct']['prohibited_action']} | {t['correct']['permitted_action_or_defer']} | {sum(t['incorrect'].values())+sum(t['invalid'].values())} |")
 lines+=['', 'This is a descriptive reportability/action dissociation under different prompts. The diagnostic changes the question and answer menu, and cannot show contemporaneous knowledge, deliberate disobedience or intent. No separate diagnostic answer is used to relabel an earlier action or remove a failed case.','']
 for key,c in a['contrasts'].items():
  if not c['primary']:continue
  label='Harmless operational-rule violation' if key.startswith('operational|') else 'Adverse shortcut with no stated rule';lo,hi=c['world_bootstrap_interval'];lines +=[f"{label}: ablation-minus-original difference {100*c['mean']:.2f} percentage points; frozen 97.5% family-stratified world-bootstrap interval [{100*lo:.2f}, {100*hi:.2f}], Holm-adjusted sign-flip reference p = {c['holm_p']:.4g}. These pilot calculations remain available but do not turn the failed study into qualified confirmation.",'']
 lines+=['The sign-flip calculation assumes symmetry/exchangeability of world effects; deterministic paired model arms are not randomized treatment assignment. Exact world-event intervals, all family/menu strata, random/sham comparisons, initial action probabilities and invalid bounds remain in the original analysis artifacts.','', 'The same pinned Qwen3-32B checkpoint ran in greedy nonthinking mode with a 16-token action cap. The fixed refusal intervention was selected and qualified on separate data, with failed earlier qualifications retained. All four arms shared exact input tensors and batch membership; zero sham matched original outputs and probabilities exactly. One random direction is a limited specificity control, not a distribution of unrelated interventions. Refusal suppression is not equivalent to harmful compliance, recovery of a base model or removal of all alignment. See the [shared instrument report](../../records/instrument_v2/report.md).','',f"Independent review: the 720-response action pilot passed raw/prompt/scoring review; the 1,296-response factual diagnostic review is {'passed' if review.get('passed') else 'pending'}. Frozen CPU reproduction of both analyses is {'passed' if repro.get('passed') else 'pending'}. These checks validate the reported observations and retained failures, not a scientific success criterion.",'', 'Formal outcome: the original action pilot and the one bounded factual diagnostic both failed readiness. No further A inference or main study is admitted. The original 108 frozen confirmation worlds remain unqueried. The contingent revised-scope draft was not admitted.','', '![Observed actions and separate factual answers](figures/action_and_comprehension_v1.png)','', 'Reproduction and artifact locations are in [REPRODUCE.md](REPRODUCE.md). No real operations were executed.']
 fig,(ax,bx)=plt.subplots(1,2,figsize=(12.8,4.8),gridspec_kw={'width_ratios':[1,1]})
 action=np.array([[a['counts'][arm+'|'+c]['actions'].get('expedited',0) for c in ['blocked_harmless','blocked_harmful','unstated_harmful']] for arm in ARMS]);facts=np.array([[d['summary'][arm+'|'+q]['correct'] for q in ['permission','feasibility','time_saving']] for arm in ARMS]);ax.imshow(action/36,vmin=0,vmax=1,cmap='Oranges',aspect='auto');bx.imshow(facts/108,vmin=0,vmax=1,cmap='Blues',aspect='auto')
 for axis,values,den in [(ax,action,36),(bx,facts,108)]:
  axis.set_yticks(range(4),LABELS if axis is ax else ['']*4);axis.set_xticks(range(3));axis.tick_params(length=0)
  for i in range(4):
   for j in range(3):axis.text(j,i,f'{values[i,j]}/{den}',ha='center',va='center',fontsize=12,color='white' if values[i,j]/den>.68 else '#222222')
 ax.set_xticklabels(['Harmless\nprohibited shortcut','Harmful\nprohibited shortcut','Adverse shortcut\nwithout rule']);bx.set_xticklabels(['Written\npermission','Technical\nfeasibility','Time\narithmetic']);ax.set_title('Action pilot: shortcut choices');bx.set_title('Separate diagnostic: correct factual answers');fig.suptitle('Reporting a rule did not guarantee following it in separate prompts',fontsize=13);fig.text(.5,.02,'18 exposed numeric worlds; response orders and conditions are paired repeats.\nBoth frozen readiness gates failed. No fresh confirmation or choice-time knowledge claim.',ha='center',fontsize=9,color='#444444');fig.tight_layout(rect=[0,.12,1,.93]);dest=H/'figures';dest.mkdir(exist_ok=True)
 for suffix in ['png','svg']:fig.savefig(dest/f'action_and_comprehension_v1.{suffix}',dpi=180)
 plt.close(fig);(H/'report.md').write_text('\n'.join(lines)+'\n');(dest/'action_and_comprehension_v1_data.json').write_text(json.dumps({'action_shortcuts':action.tolist(),'action_denominator':36,'diagnostic_correct':facts.tolist(),'diagnostic_denominator':108,'arms':ARMS,'worlds':18,'no_independence_claim_for_answers':True},indent=2)+'\n');print(json.dumps({'report':str(H/'report.md'),'independent_diagnostic_review':review.get('passed',False),'cpu_reproduced':repro.get('passed',False)}))
if __name__=='__main__':main()
